from pathlib import Path
from html.parser import HTMLParser
root=Path('/app/output')
files=['index.html','chart.html','ideas.html','markets.html','brokers.html']
class P(HTMLParser):
    def error(self, message):
        raise Exception(message)
for f in files:
    text=(root/f).read_text()
    P().feed(text)
    for link in ['styles.css','app.js']:
        if link not in text: raise SystemExit(f'{f} missing {link}')
print('HTML parsed and assets linked')
print('\n'.join(str(p.relative_to(root)) for p in sorted(root.iterdir())))
